:root{--black:#070707;--black-2:#0d0d0d;--panel:#111111;--line:#292929;--text:#f4f1eb;--muted:#9b9b9b;--red:#d7131b;--red-dark:#8e0c11;--max:1440px;}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{margin:0;background:var(--black);color:var(--text);font-family:"Manrope",Arial,sans-serif;line-height:1.55;overflow-x:clip;}
a{color:inherit;text-decoration:none;}
img{max-width:100%;display:block;}
.wrap{width:min(calc(100% - 64px),var(--max));margin:auto;}
.eyebrow{text-transform:uppercase;letter-spacing:.18em;font-size:12px;font-weight:700;color:#bcbcbc;}
.red{color:var(--red);}
.inline-red{color:var(--red);font-weight:700;}
.display{font-family:"Oswald","Arial Narrow",sans-serif;text-transform:uppercase;letter-spacing:-.035em;line-height:.88;}
header{position:fixed;z-index:40;top:0;left:0;right:0;width:100%;border:0;border-bottom:1px solid rgba(255,255,255,.14);border-radius:0;background:rgba(7,7,7,.34);-webkit-backdrop-filter:blur(24px) saturate(145%);backdrop-filter:blur(24px) saturate(145%);box-shadow:inset 0 1px 0 rgba(255,255,255,.055),0 12px 36px rgba(0,0,0,.10);}
header::before{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(105deg,rgba(255,255,255,.045),transparent 30%,transparent 78%,rgba(255,255,255,.018));}
header .nav{position:relative;z-index:1;}
.nav{min-height:74px;display:flex;align-items:center;justify-content:space-between;gap:24px;}
.brand{font-family:"Oswald",sans-serif;font-weight:700;font-size:23px;letter-spacing:.04em;}
.brand span{color:var(--red);}
nav{display:flex;gap:28px;align-items:center;}
nav a{text-transform:uppercase;font-size:11px;letter-spacing:.15em;color:#cfcfcf;}
nav a:hover{color:white;}
.nav-cta{border:1px solid #444;padding:11px 16px;}
.hero{position:relative;height:100svh;min-height:0;padding-top:74px;display:flex;align-items:stretch;overflow:hidden;border-bottom:1px solid rgba(255,255,255,.12);background:#060606;}
.hero-bg,.hero-shade,.hero-gridlines,.hero-bottom-space{position:absolute;inset:0;}
.hero-bg{background-image:url("data:image/png;base64,");background-repeat:no-repeat;background-size:cover;background-position:center top;}
.hero-shade{background:
    linear-gradient(90deg, rgba(0,0,0,.87) 0%, rgba(0,0,0,.78) 27%, rgba(0,0,0,.54) 43%, rgba(0,0,0,.15) 62%, rgba(0,0,0,.05) 100%),
    linear-gradient(180deg, rgba(0,0,0,.06) 0%, rgba(0,0,0,.16) 100%);z-index:1;}
.hero-gridlines{z-index:2;opacity:.14;background-image:
    linear-gradient(rgba(255,255,255,.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.05) 1px, transparent 1px);background-size:64px 64px;}
.hero-grid{position:relative;z-index:3;height:calc(100svh - 74px);min-height:0;display:flex;align-items:center;padding:24px 0 46px;}
.hero-copy{width:min(100%, 590px);margin-top:22px;}
.hero-title{margin:0 0 18px;font-size:clamp(88px, 18vh, 164px);line-height:.83;}
.title-line{display:block;}
.title-main{color:#f4f1eb;}
.surname{position:relative;display:block;width:max-content;margin-left:7.4vw;color:transparent;-webkit-text-stroke:1px rgba(255,255,255,.32);text-stroke:1px rgba(255,255,255,.32);}
.surname::after{content:attr(data-text);position:absolute;inset:0;color:var(--red);opacity:0;animation:redLampPulse 3.7s infinite;}
.hero-lead{max-width:500px;font-size:clamp(15px, 1.7vh, 18px);line-height:1.55;color:#e2dfd8;margin:0 0 22px;}
.hero-actions{display:flex;gap:12px;flex-wrap:wrap;}
.hero-bottom-space{top:auto;height:26px;inset-inline:0;bottom:0;background:transparent;z-index:4;}
@keyframes redLampPulse{0%, 74%, 100% { opacity:0; }
  76% { opacity:.85; }
  78% { opacity:0; }
  80% { opacity:1; }
  83% { opacity:.25; }
  85% { opacity:1; }
  91% { opacity:1; }
  93% { opacity:.18; }
  96% { opacity:0; }}
.social-strip{height:76px;display:flex;align-items:center;background:#080808;border-top:1px solid rgba(255,255,255,.10);border-bottom:1px solid rgba(255,255,255,.08);}
.social-strip-inner{width:100%;padding:0 50px;display:flex;align-items:center;justify-content:space-between;gap:30px;}
.social-label,.social-links a{font-family:"Courier New",monospace;text-transform:uppercase;letter-spacing:.12em;font-weight:700;line-height:1;color:#bd1d20;}
.social-label{font-size:15px;}
.social-links{display:flex;align-items:center;gap:28px;flex-wrap:wrap;}
.social-links a{display:inline-flex;align-items:center;gap:9px;font-size:15px;transition:color .2s ease,transform .2s ease;}
.social-links a:hover{color:#d84b4b;transform:translateY(-1px);}
.social-links svg{display:block;width:22px;height:22px;flex:0 0 22px;fill:currentColor;}
.social-links .icon-youtube{width:24px;height:24px;flex-basis:24px;}
.numbers{border-bottom:1px solid var(--line);overflow:hidden;background:#080808;}
.numbers-grid{display:grid;grid-template-columns:repeat(4,1fr);width:100%;}
.number{min-height:210px;padding:46px 50px 38px;display:flex;flex-direction:column;justify-content:center;border-right:1px solid var(--line);}
.number:last-child{border-right:0;}
.number strong{display:block;margin-bottom:12px;font-family:"Oswald","Arial Narrow",sans-serif;font-size:clamp(72px,5vw,98px);font-weight:600;line-height:.92;letter-spacing:-.035em;color:#f4f1eb;white-space:nowrap;}
.number > span:last-child{color:#a9adb4;font-size:13px;line-height:1.35;}
.counter{font-variant-numeric:tabular-nums;display:inline-block;}
section{padding:110px 0;}
.section-head{display:grid;grid-template-columns:1fr 2fr;gap:6vw;margin-bottom:64px;}
.section-head h2{margin:0;font-size:clamp(56px,7vw,104px);}
.section-head p{margin:8px 0 0;max-width:760px;color:#b9b7b2;font-size:18px;}
.about{background:#0a0a0a;border-bottom:1px solid var(--line);}
.projects{border-bottom:1px solid var(--line);}
.project-grid{display:grid;grid-template-columns:repeat(12,1fr);gap:18px;}
.project.large{grid-column:span 7;min-height:540px;}
.project.mid{grid-column:span 5;min-height:540px;}
.project.third{grid-column:span 4;min-height:360px;}
.project.half{grid-column:span 6;min-height:360px;}
.credentials{height:100svh;min-height:720px;padding:0;background:#f1ede7;color:#090909;border-bottom:1px solid #d3ccc4;overflow:hidden;}
.credentials .eyebrow{color:#655d56;align-self:start;padding-top:8px;}
.press{border-bottom:1px solid var(--line);}
.contact{padding:0;background:var(--red);color:white;}
.contact-inner{min-height:72vh;padding:90px 0 60px;display:flex;flex-direction:column;justify-content:space-between;}
.contact h2{margin:15px 0;font-size:clamp(72px,10.5vw,170px);max-width:1200px;}
.contact .eyebrow{display:inline-block;padding:0;background:none;box-shadow:none;color:#fff !important;}
.contact .eyebrow::after{display:none;content:none;}
.contact-text{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:end;}
.contact-text p{max-width:640px;margin:0;font-size:20px;font-weight:600;line-height:1.45;}
.mail{position:relative;display:inline-block;width:max-content;max-width:100%;justify-self:end;text-align:right;font:500 clamp(22px,3vw,44px)/1 "Oswald",sans-serif;text-transform:uppercase;padding-bottom:12px;overflow-wrap:anywhere;}
.mail::after,.mail::before{content:"";position:absolute;left:0;bottom:0;height:2px;background:#fff;}
.mail::after{right:0;opacity:.45;}
.mail::before{width:0;transition:width .34s ease;z-index:1;}
.mail:hover::before,.mail:focus-visible::before{width:100%;}
footer.site-footer-shell{padding:0;background:transparent;color:#777;font-size:11px;text-transform:uppercase;letter-spacing:.1em;overflow:hidden;}
.footer-bar{background:#050505;padding:24px 0 20px;}
.footer-inner{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:22px 28px;}
.footer-pages{grid-column:1/-1;grid-row:1;display:flex;justify-content:center;align-items:center;gap:22px;flex-wrap:wrap;padding-bottom:18px;border-bottom:1px solid rgba(255,255,255,.10);}
.footer-pages a{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:#9b9b9b;transition:color .2s ease;}
.footer-pages a:hover{color:#fff;}
.footer-meta{display:contents;}
.footer-meta span:first-child{grid-column:1;grid-row:2;justify-self:start;white-space:nowrap;}
.footer-meta span:last-child{grid-column:3;grid-row:2;justify-self:end;white-space:nowrap;text-align:right;}
.footer-social{grid-column:2;grid-row:2;display:flex;justify-content:center;min-width:0;}
.footer-social .social-links{justify-content:center;gap:36px;flex-wrap:nowrap;white-space:nowrap;color:var(--red);}
.footer-social .social-links a{font-family:"Courier New",monospace;font-size:15px;font-weight:700;letter-spacing:.12em;line-height:1;text-transform:uppercase;color:var(--red);}
.footer-social .social-links a:hover{color:#ff3b3b;transform:translateY(-1px);}
.footer-social .social-links svg{width:22px;height:22px;flex-basis:22px;}
.footer-social .social-links .icon-youtube{width:24px;height:24px;flex-basis:24px;}
@media (max-width:1180px){
  .footer-inner{gap:18px;}
  .footer-pages{gap:14px 18px;}
  .footer-social .social-links{gap:20px;}
  .footer-social .social-links a{font-size:12px;gap:7px;}
  .footer-social .social-links svg{width:18px;height:18px;flex-basis:18px;}
  .footer-social .social-links .icon-youtube{width:20px;height:20px;flex-basis:20px;}
  .footer-meta span{font-size:9px;}
}
@media (max-width:820px){
  .footer-bar{padding:26px 0 30px;}
  .footer-inner{grid-template-columns:1fr;gap:20px;}
  .footer-pages{grid-column:1;grid-row:1;justify-content:flex-start;width:100%;padding-bottom:18px;gap:14px 18px;}
  .footer-social{grid-column:1;grid-row:2;justify-content:flex-start;width:100%;}
  .footer-social .social-links{justify-content:flex-start;flex-wrap:wrap;white-space:normal;gap:16px 20px;}
  .footer-meta span:first-child{grid-column:1;grid-row:3;justify-self:start;white-space:normal;}
  .footer-meta span:last-child{grid-column:1;grid-row:4;justify-self:start;white-space:normal;text-align:left;}
}
@media (max-width:680px){
  .footer-pages a{font-size:9px;}
  .footer-social .social-links a{font-size:11px;}
  .footer-social .social-links svg{width:17px;height:17px;flex-basis:17px;}
  .footer-social .social-links .icon-youtube{width:19px;height:19px;flex-basis:19px;}
}

